    for k in ("coordinates", "coords", "locations"):
        if k in instance:
            coords = instance[k]
            break

    matrix = None
    for k in ("distance_matrix", "dist_matrix", "cost_matrix"):
        if k in instance:
            matrix = instance[k]
            break

    def customer_ids():
        if "customers" in instance and instance["customers"] is not None:
            return list(instance["customers"])
        if isinstance(demands, dict):
            return [c for c in demands.keys() if c != depot]
        if is_seq(coords):
            n = len(coords)
            return [i for i in range(n) if i != depot]
        if is_seq(matrix):
            n = len(matrix)
            return [i for i in range(n) if i != depot]
        if "n_customers" in instance:
            n = instance["n_customers"]
            if depot == 0:
                return list(range(1, n + 1))
            return [i for i in range(1, n + 1) if i != depot]
        if is_seq(demands):
            n = len(demands)
            return [i for i in range(n) if i != depot]
        return []

    customers = customer_ids()

    def demand(c):
        if isinstance(demands, dict):
            return demands.get(c, 1)
        if is_seq(demands):
            if 0 <= c < len(demands):
                return demands[c]
            if 1 <= c <= len(demands) - 1:
                return demands[c]
        return 1

    def dist(a, b):
        if matrix is not None:
            if isinstance(matrix, dict):
                if (a, b) in matrix:
                    return matrix[(a, b)]
                if (b, a) in matrix:
                    return matrix[(b, a)]
            else:
                try:
                    return matrix[a][b]
                except Exception:
                    pass
        if coords is not None:
            try:
                ax, ay = coords[a]
                bx, by = coords[b]
                dx = ax - bx
                dy = ay - by
                return (dx * dx + dy * dy) ** 0.5
            except Exception:
                pass
        return abs(a - b)

    def route_load(route):
        s = 0
        for c in route:
            s += demand(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        cst = dist(depot, route[0])
        i = 0
        while i + 1 < len(route):
            cst += dist(route[i], route[i + 1])
            i += 1
        cst += dist(route[-1], depot)
        return cst

    def insertion_cost(route, pos, c):
        prev_n = depot if pos == 0 else route[pos - 1]
        next_n = depot if pos == len(route) else route[pos]
        return dist(prev_n, c) + dist(c, next_n) - dist(prev_n, next_n)

    def route_interior_2opt(route):
        if len(route) < 4:
            return route
        improved = True
        while improved:
            improved = False
            best_delta = 0
            best_i = -1
            best_j = -1
            n = len(route)
            i = 0
            while i < n - 2:
                a = depot if i == 0 else route[i - 1]
                b = route[i]
                j = i + 1
                while j < n:
                    c = route[j]
                    d = depot if j == n - 1 else route[j + 1]
                    delta = dist(a, c) + dist(b, d) - dist(a, b) - dist(c, d)
                    if delta < best_delta:
                        best_delta = delta
                        best_i = i
                        best_j = j
                    j += 1
                i += 1
            if best_delta < -1e-12:
                route = route[:best_i] + route[best_i:best_j + 1][::-1] + route[best_j + 1:]
                improved = True
        return route

    def optimize_routes(routes):
        changed = True
        while changed:
            changed = False
            for idx in range(len(routes)):
                newr = route_interior_2opt(routes[idx])
                if newr != routes[idx]:
                    routes[idx] = newr
                    changed = True

            # cross-route relocate
            r1 = 0
            while r1 < len(routes):
                r2 = 0
                moved_any = False
                while r2 < len(routes):
                    if r1 != r2 and routes[r1]:
                        best_move = None
                        best_delta = 0
                        for i in range(len(routes[r1])):
                            c = routes[r1][i]
                            dc = demand(c)
                            if route_load(routes[r2]) + dc > capacity:
                                continue
                            # remove from r1
                            prev1 = depot if i == 0 else routes[r1][i - 1]
                            next1 = depot if i == len(routes[r1]) - 1 else routes[r1][i + 1]
                            rem = dist(prev1, c) + dist(c, next1) - dist(prev1, next1)
                            pos = 0
                            while pos <= len(routes[r2]):
                                add = insertion_cost(routes[r2], pos, c)
                                delta = add - rem
                                if delta < best_delta:
                                    best_delta = delta
                                    best_move = (i, pos, c)
                                pos += 1
                        if best_move is not None:
                            i, pos, c = best_move
                            routes[r1].pop(i)
                            if not routes[r1]:
                                routes.pop(r1)
                                if r2 > r1:
                                    r2 -= 1
                            if r1 < len(routes) and r2 < len(routes):
                                routes[r2].insert(pos, c)
                            changed = True
                            moved_any = True
                            break
                    r2 += 1
                if not moved_any:
                    r1 += 1
                else:
                    break

            # remove empty routes
            routes = [r for r in routes if r]
        return routes

    unserved = {}
    for c in customers:
        unserved[c] = True

    routes = []

    # Greedy route construction with farthest seeds and cheapest insertion.
    while unserved:
        seed = None
        seed_key = None
        for c in unserved:
            dc = demand(c)
            key = (dist(depot, c), dc, c)
            if seed is None or key > seed_key:
                seed = c
                seed_key = key
        route = [seed]
        load = demand(seed)
        del unserved[seed]

        while True:
            best_c = None
            best_pos = None
            best_key = None
            for c in unserved:
                dc = demand(c)
                if load + dc > capacity:
                    continue
                # cheapest insertion position
                pos = 0
                local_best = None
                local_pos = 0
                while pos <= len(route):
                    inc = insertion_cost(route, pos, c)
                    key = (inc, dist(depot, c), dc, c, pos)
                    if local_best is None or key < local_best:
                        local_best = key
                        local_pos = pos
                    pos += 1
                if local_best is not None:
                    if best_key is None or local_best < best_key:
                        best_key = local_best
                        best_c = c
                        best_pos = local_pos
            if best_c is None:
                break
            route.insert(best_pos, best_c)
            load += demand(best_c)
            del unserved[best_c]

        routes.append(route)

    routes = optimize_routes(routes)

    # Final deterministic refinement: try to merge/swap by relocating from small routes.
    improved = True
    while improved:
        improved = False
        routes.sort(key=lambda r: (route_load(r), len(r), route_cost(r)))
        i = 0
        while i < len(routes):
            if not routes[i]:
                routes.pop(i)
                improved = True
                continue
            j = 0
            while j < len(routes):
                if i != j and routes[i]:
                    moved = False
                    a = 0
                    while a < len(routes[i]):
                        c = routes[i][a]
                        dc = demand(c)
                        if route_load(routes[j]) + dc <= capacity:
                            prev1 = depot if a == 0 else routes[i][a - 1]
                            next1 = depot if a == len(routes[i]) - 1 else routes[i][a + 1]
                            rem = dist(prev1, c) + dist(c, next1) - dist(prev1, next1)
                            best_pos = None
                            best_delta = 0
                            p = 0
                            while p <= len(routes[j]):
                                add = insertion_cost(routes[j], p, c)
                                delta = add - rem
                                if delta < best_delta:
                                    best_delta = delta
                                    best_pos = p
                                p += 1
                            if best_pos is not None:
                                routes[i].pop(a)
                                routes[j].insert(best_pos, c)
                                improved = True
                                moved = True
                                break
                        a += 1
                    if moved:
                        if not routes[i]:
                            routes.pop(i)
                            improved = True
                            break
                j += 1
            else:
                i += 1

    routes = [r for r in routes if r]

    # Safety: if any customer somehow unserved, append as singleton in deterministic order.
    served = {}
    for r in routes:
        for c in r:
            served[c] = True
    missing = []
    for c in customers:
        if c not in served:
            missing.append(c)
    missing.sort()
    for c in missing:
        routes.append([c])

    return routes
